-- Phase 1 ONLY. Select intended database, run preflight and export backup first.
-- No account DML. Stop on any DDL error. No Nurse clinical schema is applied.
SET @doctor_ready=DATABASE() IS NOT NULL AND @@FOREIGN_KEY_CHECKS=1 AND NOT EXISTS(SELECT 1 FROM (SELECT 'users.id' AS item, CASE WHEN c.COLUMN_NAME IS NULL THEN 'BLOCK' WHEN c.DATA_TYPE='int' AND c.IS_NULLABLE='NO' AND c.EXTRA LIKE '%auto_increment%' AND c.EXTRA NOT LIKE '%GENERATED%' THEN 'PASS' ELSE 'BLOCK' END AS result FROM (SELECT 1) seed LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME='users' AND c.COLUMN_NAME='id'
