UNION ALL
SELECT 'admin_profiles.user_id' AS item, CASE WHEN c.COLUMN_NAME IS NULL THEN 'BLOCK' WHEN c.COLUMN_TYPE=(SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='users' AND COLUMN_NAME='id') AND c.IS_NULLABLE='NO' AND c.EXTRA NOT LIKE '%GENERATED%' THEN 'PASS' ELSE 'BLOCK' END AS result FROM (SELECT 1) seed LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME='admin_profiles' AND c.COLUMN_NAME='user_id'
