UNION ALL SELECT 'unexpected unique invitation index',INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='admin_invitations' AND NON_UNIQUE=0 AND INDEX_NAME<>'PRIMARY' GROUP BY INDEX_NAME HAVING COUNT(*)<>1 OR MAX(COLUMN_NAME)<>'token_hash'
UNION ALL SELECT 'invitation CHECK constraint needs review',CONSTRAINT_NAME FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='admin_invitations' AND CONSTRAINT_TYPE='CHECK') custom_checks));
SELECT IF(@doctor_complete,'SCHEMA_COMPLETE - run post-verification','BLOCK_OR_INCOMPLETE') migration_result;
